UPDATE intake_entries SET name = :name, servings = :servings, eaten_at = :eaten_at, day = :day, kcal = :kcal, protein_g = :protein_g, carbs_g = :carbs_g, fat_g = :fat_g, fiber_g = :fiber_g, kcal_low = :kcal_low, kcal_high = :kcal_high, provenance = :provenance, source = :source, portion_note = :portion_note, updated_at = :updated_at WHERE user_id = :user_id AND id = :id RETURNING *;
